-- Phase 3 remains isolated in pm_* and only attaches the reserved nullable FK.
CREATE TABLE IF NOT EXISTS pm_materials (id BIGSERIAL PRIMARY KEY,name VARCHAR(200) NOT NULL UNIQUE,unit VARCHAR(40),category VARCHAR(100),min_stock_level NUMERIC(14,3) NOT NULL DEFAULT 0,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
ALTER TABLE pm_vendor_material_supply ADD CONSTRAINT pm_vendor_material_supply_material_id_fkey FOREIGN KEY(material_id) REFERENCES pm_materials(id) ON DELETE SET NULL;
CREATE TABLE IF NOT EXISTS pm_material_received (id BIGSERIAL PRIMARY KEY,project_id BIGINT NOT NULL REFERENCES pm_projects(id) ON DELETE RESTRICT,material_id BIGINT NOT NULL REFERENCES pm_materials(id) ON DELETE RESTRICT,supplier_name TEXT,supplier_vendor_id BIGINT REFERENCES pm_vendors(id) ON DELETE SET NULL,vendor_supply_id BIGINT REFERENCES pm_vendor_material_supply(id) ON DELETE SET NULL,quantity NUMERIC(14,3) NOT NULL CHECK(quantity>0),rate NUMERIC(14,2) NOT NULL CHECK(rate>=0),amount NUMERIC(14,2) NOT NULL CHECK(amount>=0),received_date DATE NOT NULL,challan_no VARCHAR(100),note TEXT,is_deleted BOOLEAN NOT NULL DEFAULT FALSE,created_by TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ,transfer_in BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS pm_material_used (id BIGSERIAL PRIMARY KEY,project_id BIGINT NOT NULL REFERENCES pm_projects(id) ON DELETE RESTRICT,material_id BIGINT NOT NULL REFERENCES pm_materials(id) ON DELETE RESTRICT,quantity NUMERIC(14,3) NOT NULL CHECK(quantity>0),used_date DATE NOT NULL,used_for TEXT,note TEXT,is_deleted BOOLEAN NOT NULL DEFAULT FALSE,created_by TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ,over_used BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS pm_material_adjustments (id BIGSERIAL PRIMARY KEY,project_id BIGINT NOT NULL REFERENCES pm_projects(id) ON DELETE RESTRICT,material_id BIGINT NOT NULL REFERENCES pm_materials(id) ON DELETE RESTRICT,adjustment_type VARCHAR(30) NOT NULL CHECK(adjustment_type IN ('wastage','damage','return_to_supplier','transfer_out')),quantity NUMERIC(14,3) NOT NULL CHECK(quantity>0),adjustment_date DATE NOT NULL,to_project_id BIGINT REFERENCES pm_projects(id) ON DELETE RESTRICT,note TEXT,is_deleted BOOLEAN NOT NULL DEFAULT FALSE,created_by TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),over_used BOOLEAN NOT NULL DEFAULT FALSE);
CREATE TABLE IF NOT EXISTS pm_other_expenses (id BIGSERIAL PRIMARY KEY,project_id BIGINT NOT NULL REFERENCES pm_projects(id) ON DELETE RESTRICT,category VARCHAR(30) NOT NULL CHECK(category IN ('transport','machine_rent','electricity_water','permit','misc')),amount NUMERIC(14,2) NOT NULL CHECK(amount>0),expense_date DATE NOT NULL,note TEXT,is_deleted BOOLEAN NOT NULL DEFAULT FALSE,created_by TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS pm_received_project_idx ON pm_material_received(project_id); CREATE INDEX IF NOT EXISTS pm_received_material_idx ON pm_material_received(material_id); CREATE INDEX IF NOT EXISTS pm_received_supplier_vendor_idx ON pm_material_received(supplier_vendor_id); CREATE INDEX IF NOT EXISTS pm_received_vendor_supply_idx ON pm_material_received(vendor_supply_id); CREATE INDEX IF NOT EXISTS pm_used_project_idx ON pm_material_used(project_id); CREATE INDEX IF NOT EXISTS pm_used_material_idx ON pm_material_used(material_id); CREATE INDEX IF NOT EXISTS pm_adjustments_project_idx ON pm_material_adjustments(project_id); CREATE INDEX IF NOT EXISTS pm_adjustments_material_idx ON pm_material_adjustments(material_id); CREATE INDEX IF NOT EXISTS pm_adjustments_to_project_idx ON pm_material_adjustments(to_project_id); CREATE INDEX IF NOT EXISTS pm_other_expenses_project_idx ON pm_other_expenses(project_id); CREATE INDEX IF NOT EXISTS pm_stock_project_material_date_idx ON pm_material_received(project_id,material_id,received_date);
